function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}
function sqlJson(value) {
  return `${sql(JSON.stringify(value ?? {}))}::jsonb`;
}
function slug(value, fallback = '') { return String(value || fallback || '').trim(); }
const body=$json.body||{}; const avatar=slug(body.avatar); const scene=slug(body.scene); const assetType=slug(body.assetType||body.asset_type,'raw-image'); const platform=slug(body.platform,'instagram'); const baseUrl=slug(body.baseUrl||body.base_url,'http://192.168.0.194:9000').replace(/\/$/,''); const brief=body.brief||{}; const re=/^[a-z0-9][a-z0-9-]*$/i;
if(!re.test(avatar)||!re.test(scene)||!re.test(assetType)) return {json:{ok:false,skipQuery:true,error:'avatar, scene and assetType are required slug-like values',request:{avatar,scene,assetType}}};
const query=`WITH refs AS (SELECT asset_id,bucket,object_path,status,is_canonical,created_at FROM canonical_asset_registry WHERE avatar=${sql(avatar)} AND scene=${sql(scene)} AND asset_type=${sql(assetType)} AND COALESCE(status,'') IN ('canonical','selected','raw') ORDER BY CASE WHEN COALESCE(is_canonical,false)=true OR status='canonical' THEN 1 WHEN status='selected' THEN 2 WHEN status='raw' THEN 3 ELSE 4 END, created_at DESC LIMIT 6) SELECT ac.avatar, ${sql(scene)} AS scene, ${sql(assetType)} AS asset_type, ${sql(platform)} AS platform, ac.display_name AS avatar_display_name, ac.avatar_short, sc.display_name AS scene_display_name, COALESCE(sb.visual_intent,sc.description,sc.display_name,sc.scene) AS visual_intent, COALESCE(sb.allowed_mood,'natural, cinematic, emotionally warm') AS allowed_mood, COALESCE(sb.avoid,'[]'::jsonb) AS avoid, COALESCE(sb.prompt_notes,'') AS prompt_notes, COALESCE((SELECT jsonb_agg(jsonb_build_object('assetId',asset_id,'status',status,'isCanonical',is_canonical,'objectPath',object_path,'url',${sql(baseUrl)} || '/' || bucket || '/' || object_path)) FROM refs),'[]'::jsonb) AS reference_images FROM avatar_catalog ac JOIN scene_catalog sc ON sc.avatar=ac.avatar AND sc.scene=${sql(scene)} LEFT JOIN scene_brief_catalog sb ON sb.avatar=ac.avatar AND sb.scene=sc.scene WHERE ac.avatar=${sql(avatar)} LIMIT 1;`;
return {json:{ok:true,skipQuery:false,query,brief}};

const row=$input.first()?.json||{}; const params=$('Build Prompt Pack Query').first().json; if(!row.avatar) return [{json:{ok:false,error:'Prompt pack context not found'}}];
function parse(v,f){if(v==null)return f;if(typeof v==='string'){try{return JSON.parse(v)}catch{return f}}return v} const avoid=parse(row.avoid,[]); const referenceImages=parse(row.reference_images,[]); const brief=params.brief||{};
const positivePrompt=[row.avatar_display_name||row.avatar,row.visual_intent,brief.promptIntent||'',brief.visualDirection||'',row.allowed_mood,row.prompt_notes,'photorealistic, natural skin texture, candid lifestyle photography, consistent identity, high quality'].filter(Boolean).join(', ');
const negativePrompt=['cartoon, anime, illustration, plastic skin, overprocessed face, distorted hands, extra fingers, bad anatomy','low quality, blurry, duplicate person, wrong identity, heavy makeup, unrealistic body proportions',...(Array.isArray(avoid)?avoid:[])].filter(Boolean).join(', ');
return [{json:{ok:true,avatar:row.avatar,scene:row.scene,assetType:row.asset_type,platform:row.platform,positivePrompt,negativePrompt,referenceImages,promptMetadata:{avatarDisplayName:row.avatar_display_name,avatarShort:row.avatar_short,sceneDisplayName:row.scene_display_name,visualIntent:row.visual_intent,allowedMood:row.allowed_mood}}}];
